programs._raw:
{
  "name": "Property Tax/Rent Rebate Program",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "household_income_cap": 48110,
      "standard_rebate_table": [
        {
          "income_range": "$0 - $8,550",
          "max_rebate": "$1,000"
        },
        {
          "income_range": "$8,551 - $16,040",
          "max_rebate": "$770"
        },
        {
          "income_range": "$16,041 - $19,240",
          "max_rebate": "$460"
        },
        {
          "income_range": "$19,241 - $48,110",
          "max_rebate": "$380"
        }
      ],
      "who_qualifies": [
        "Pennsylvanians age 65 and older",
        "Widows and widowers age 50 and older",
        "People with disabilities age 18 and older"
      ],
      "notes": [
        "Eligibility is based on annual income and the amount paid in property taxes or rent during the previous year.",
        "Applicants must reapply every year."
      ]
    },
    "asset_limits": "No asset limit was identified in the official program materials reviewed. The program is income-based, not asset-based.",
    "other_requirements": [
      "Must be a Pennsylvania resident.",
      "Must have paid property taxes or rent on a primary residence in Pennsylvania during the previous calendar year.",
      "Must file a new claim each year using PA-1000.",
      "Renter applicants must submit a PA-1000 RC (Rent Certificate)."
    ]
  },
  "benefits": {
    "type": "financial",
    "value": "Annual rebate on property taxes or rent paid in the previous year. Standard maximum rebate amounts are $1,000, $770, $460, or $380 depending on income. For property owners with $32,070 or less in income whose property taxes exceed 15% of total income, the rebate is automatically calculated under an enhanced formula.",
    "varies_by": "household_size"
  },
  "application": {
    "methods": [
      "Online at myPATH: https://mypath.pa.gov",
      "By mail to Pennsylvania Department of Revenue, Property Tax/Rent Rebate Program, P.O. Box 280503, Harrisburg, PA 17128-0503",
      "In-person help at statewide locations",
      "Phone assistance at 1-888-222-9190"
    ],
    "processing_time": "No official fixed processing time was identified in the materials reviewed. Rebates are distributed after claims are processed, and applicants should expect the timeline to vary based on filing method and claim volume.",
    "waitlist": null,
    "forms": [
      "PA-1000 — Property Tax or Rent Rebate Claim",
      "PA-1000 RC — Rent Certificate",
      "PA-1000 instructions / preparation guide"
    ],
    "documents": [
      "Completed PA-1000 claim form",
      "Proof of income",
      "Property tax receipts for homeowners",
      "PA-1000 RC Rent Certificate for renters",
      "Any supporting documentation requested in the instructions"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Available statewide in Pennsylvania; no county-specific eligibility restriction identified.",
    "regional_variations": "The program itself is statewide and the benefit rules are the same across Pennsylvania. Help with filing may vary by local office or assistance site, but eligibility and rebate calculations do not vary by region.",
    "offices_or_providers": [
      "Pennsylvania Department of Revenue statewide assistance locations",
      "Local county assistance sites that help with filing"
    ]
  },
  "official_source": "https://www.pa.gov/agencies/revenue/ptrr",
  "gotchas": [
    "This is a rebate program, not ongoing monthly aid.",
    "People must file a new application every year; approval does not carry over.",
    "Renter applicants often miss the PA-1000 RC rent certificate requirement.",
    "The rebate is based on prior-year taxes or rent and prior-year income, not current-year circumstances.",
    "The highest rebate is not for everyone; it depends on where income falls in the tier table.",
    "The enhanced automatic calculation can apply to some homeowners with low income and high property taxes, which many applicants overlook."
  ],
  "data_shape_notes": "This program is a statewide annual financial rebate with age-based eligibility and income-tiered benefit amounts. It is not a service program, does not use a waitlist, and requires a fresh annual application."
}
